-- MAWATHEQ — lawyer specialty backfill (data-only)
--
-- Generated by tools/generate_lawyer_specialty_backfill.php on 2026-10-24.
--
-- PURPOSE
--   Make approved lawyers visible in the consultation journey on a server whose
--   includes/legal_journey.php predates the declared-specialization fallback.
--   It writes the missing lawyer_specialties rows, so both the old and the new
--   code find the lawyer. The new code treats an explicit link as authoritative,
--   so running this before the code deploy changes nothing once the code lands.
--
-- HOW IT WORKS
--   One INSERT ... SELECT. It matches each approved lawyer's own declared
--   specialization to a live category through the same map the runtime uses,
--   and inserts the link. It reads the target server's own rows, so no id from
--   another machine is embedded and the file is correct on any deployment.
--
-- SAFETY
--   * INSERT IGNORE only. Unique key (lawyer_id, category_id): a second run adds
--     nothing, and a link an operator made by hand is never overwritten.
--   * No UPDATE, no DELETE, no DDL, no table creation.
--   * Only approved lawyers and live categories, matching the runtime.
--   * No client, case, document or payment data is read or written.
--
-- PREREQUISITE
--   The najiz_* tables and lawyer_specialties must exist (see
--   MAWATHEQ_DB_SCHEMA_FIX.sql). This file does not create them.
--
-- REFERENCE COUNTS (from the generator's own database, for orientation only)
--   approved lawyers with a mappable specialization: 1
--   approved lawyers with no mappable specialization: 1 distinct value(s)
--     (empty)  x2
--   The target reports its own numbers in the VERIFY section below.
--
-- VERIFY AFTER RUNNING (run each SELECT on the target)
--   -- 1. how many links exist now
--   SELECT COUNT(*) AS links FROM lawyer_specialties;
--
--   -- 2. approved lawyers that are now discoverable, and under which specialty
--   SELECT l.id, l.full_name, c.name_ar AS specialty
--     FROM lawyer_specialties ls
--     JOIN lawyers l ON l.id = ls.lawyer_id
--     JOIN najiz_categories c ON c.id = ls.category_id
--    WHERE l.status = 'approved'
--    ORDER BY l.id;
--
--   -- 3. approved lawyers still not linked to anything
--   SELECT l.id, l.full_name, l.specialization
--     FROM lawyers l
--    WHERE l.status = 'approved'
--      AND NOT EXISTS (SELECT 1 FROM lawyer_specialties ls WHERE ls.lawyer_id = l.id);
--
--   Then confirm from the app:
--     GET /api/v1/journey.php?action=specialties   -> lawyer_count >= 1 for a staffed one
--     GET /api/v1/journey.php?action=lawyers&category_id=<id>  -> matched:true
--
SET NAMES utf8mb4;

INSERT IGNORE INTO lawyer_specialties (lawyer_id, category_id)
SELECT l.id, c.id
  FROM lawyers l
  JOIN (
         SELECT 'الأحوال الشخصية' AS spec, 'الأحوال الشخصية' AS cat
  UNION ALL SELECT 'قانون جنائي' AS spec, 'الدعاوى الجزائية' AS cat
  UNION ALL SELECT 'قانون تجاري' AS spec, 'الدعاوى التجارية' AS cat
  UNION ALL SELECT 'قانون شركات' AS spec, 'الدعاوى التجارية' AS cat
  UNION ALL SELECT 'التحكيم التجاري' AS spec, 'الدعاوى التجارية' AS cat
  UNION ALL SELECT 'القانون البنكي والمالي' AS spec, 'الدعاوى التجارية' AS cat
  UNION ALL SELECT 'الملكية الفكرية' AS spec, 'الدعاوى التجارية' AS cat
  UNION ALL SELECT 'قانون العمل والعمال' AS spec, 'الدعاوى العمالية' AS cat
  UNION ALL SELECT 'القانون المدني' AS spec, 'الدعاوى العامة' AS cat
  UNION ALL SELECT 'القانون الإداري' AS spec, 'الدعاوى العامة' AS cat
  UNION ALL SELECT 'قانون عقاري' AS spec, 'الدعاوى العامة' AS cat
  UNION ALL SELECT 'الضرائب والزكاة' AS spec, 'الدعاوى العامة' AS cat
  UNION ALL SELECT 'القانون الدولي' AS spec, 'الدعاوى العامة' AS cat
       ) m ON m.spec = TRIM(l.specialization)
  JOIN najiz_categories c ON c.name_ar = m.cat AND c.is_active = 1
 WHERE l.status = 'approved';
